with stale as (
  select ct.id
    from clan_town ct
    join clan c on c.id = ct.clan_id
   where not exists (select 1 from want w where w.slug = c.slug and w.name = ct.name)
)
delete from clan_town where id in (select id from stale);
update clan_town ct
   set is_head = w.is_head
  from want w, clan c
 where c.id = ct.clan_id and c.slug = w.slug and ct.name = w.name and ct.is_head <> w.is_head;
select 'clan_town rows now: ' || count(*) from clan_town;
select 'clans with no town row: ' || count(*) from clan c where not exists (select 1 from clan_town ct where ct.clan_id = c.id);
